{{ release_marker() }}
with seasons as (
    select season_end_year, phase from {{ ref('stg_player_season') }}
    union select season_end_year, phase from {{ ref('stg_team_season') }}
), origin as (
    select distinct p.source_name
    from {{ source('meta', 'release_input') }} i
    join {{ source('raw', 'source_page') }} p using (page_id)
    where i.release_id = {{ release_id() }}
)
select {{ release_id() }} as release_id, s.season_end_year, s.phase,
    exists(select 1 from {{ ref('mart_player_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase) as player_season_totals_available,
    exists(select 1 from {{ ref('mart_team_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase) as team_season_totals_available,
    false as game_detail_available, false as game_detail_complete,
    0::integer as observed_games, null::integer as expected_games,
    null::date as coverage_starts_on, null::date as coverage_through_date,
    array_remove(array[case when exists(select 1 from {{ ref('mart_player_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.minutes_seconds is null) or exists(select 1 from {{ ref('mart_team_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.minutes_seconds is null) then 'minutes_seconds' end, case when exists(select 1 from {{ ref('mart_player_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.fg is null) or exists(select 1 from {{ ref('mart_team_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.fg is null) then 'fg' end, case when exists(select 1 from {{ ref('mart_player_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.fga is null) or exists(select 1 from {{ ref('mart_team_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.fga is null) then 'fga' end, case when exists(select 1 from {{ ref('mart_player_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.fg3 is null) or exists(select 1 from {{ ref('mart_team_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.fg3 is null) then 'fg3' end, case when exists(select 1 from {{ ref('mart_player_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.fg3a is null) or exists(select 1 from {{ ref('mart_team_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.fg3a is null) then 'fg3a' end, case when exists(select 1 from {{ ref('mart_player_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.ft is null) or exists(select 1 from {{ ref('mart_team_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.ft is null) then 'ft' end, case when exists(select 1 from {{ ref('mart_player_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.fta is null) or exists(select 1 from {{ ref('mart_team_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.fta is null) then 'fta' end, case when exists(select 1 from {{ ref('mart_player_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.orb is null) or exists(select 1 from {{ ref('mart_team_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.orb is null) then 'orb' end, case when exists(select 1 from {{ ref('mart_player_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.drb is null) or exists(select 1 from {{ ref('mart_team_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.drb is null) then 'drb' end, case when exists(select 1 from {{ ref('mart_player_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.reb is null) or exists(select 1 from {{ ref('mart_team_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.reb is null) then 'reb' end, case when exists(select 1 from {{ ref('mart_player_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.ast is null) or exists(select 1 from {{ ref('mart_team_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.ast is null) then 'ast' end, case when exists(select 1 from {{ ref('mart_player_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.stl is null) or exists(select 1 from {{ ref('mart_team_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.stl is null) then 'stl' end, case when exists(select 1 from {{ ref('mart_player_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.blk is null) or exists(select 1 from {{ ref('mart_team_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.blk is null) then 'blk' end, case when exists(select 1 from {{ ref('mart_player_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.tov is null) or exists(select 1 from {{ ref('mart_team_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.tov is null) then 'tov' end, case when exists(select 1 from {{ ref('mart_player_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.pf is null) or exists(select 1 from {{ ref('mart_team_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.pf is null) then 'pf' end, case when exists(select 1 from {{ ref('mart_player_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.pts is null) or exists(select 1 from {{ ref('mart_team_season') }} m where m.season_end_year=s.season_end_year and m.phase=s.phase and m.pts is null) then 'pts' end]::text[], null) as missing_fields,
    case when o.source_name = 'demo_fixture' then
        'Synthetic demonstration subset; season summary totals only; no full-season or game coverage claim.'
    else 'Imported source season summaries; aggregate comparisons only; completeness is not verified and no game detail is loaded.' end as coverage_notes
from seasons s cross join origin o
